import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt();
        int[] contas = new int[3];
        for (int i = 0; i < 3; i++) {
            contas[i] = sc.nextInt();
        }
        Arrays.sort(contas);
        int pagas = 0;
